 /** Does an action pattern such as "doc:*" match an action such as "doc:read"? See README.md. */
 export function matchAction(pattern: string, action: string): boolean {
-  throw new Error("not implemented");
+  if (pattern === "*") return true;
+  if (pattern.endsWith(":*")) {
+    const prefix = pattern.slice(0, -1);
+    return action.startsWith(prefix) && action.length > prefix.length;
+  }
+  return pattern === action;
 }

 /** Does a resource pattern with * and ** segments match a path? See README.md. */
 export function matchResource(pattern: string, resource: string): boolean {
-  throw new Error("not implemented");
+  return matchSegments(segments(pattern), segments(resource));
 }
+
+function segments(path: string): string[] {
+  return path.split("/").filter((segment) => segment !== "");
+}
+
+function matchSegments(pattern: string[], resource: string[]): boolean {
+  if (pattern.length === 0) return resource.length === 0;
+  const [head, ...rest] = pattern;
+  if (head === "**") {
+    for (let skip = 0; skip <= resource.length; skip++) {
+      if (matchSegments(rest, resource.slice(skip))) return true;
+    }
+    return false;
+  }
+  if (resource.length === 0) return false;
+  if (head !== "*" && head !== resource[0]) return false;
+  return matchSegments(rest, resource.slice(1));
+}
